<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3'
import { computed, shallowRef } from 'vue'
import AppShell from '../../Components/AppShell.vue'
import ConfirmModal from '../../Components/ConfirmModal.vue'
import PageHeader from '../../Components/PageHeader.vue'
import FormErrorSummary from '../../Components/FormErrorSummary.vue'
import SaveActionButton from '../../Components/SaveActionButton.vue'

type User = { name?: string; username?: string; phone?: string; email?: string; email_bill_notifications_enabled?: boolean }
const props = withDefaults(defineProps<{ user?: User }>(), { user: () => ({}) })
const page = usePage<{ flash?: { status?: string } }>()
const profileForm = useForm({ name: props.user.name || '', username: props.user.username || '', phone: props.user.phone || '', email_bill_notifications_enabled: props.user.email_bill_notifications_enabled ?? true, profile_photo: null as File | null, password: '', password_confirmation: '' })
const profileRequiredIncomplete = computed(() => !profileForm.name.trim())
const emailForm = useForm({ email: props.user.email || '' })
const deleteForm = useForm({ current_password: '' })
const editConfirmationOpen = shallowRef(false)
const deleteConfirmationOpen = shallowRef(false)
function submit() { if (!profileForm.processing) editConfirmationOpen.value = true }
function confirmEditProfile() { editConfirmationOpen.value = false; profileForm.patch('/profile', { preserveScroll: true, forceFormData: true }) }
function requestEmailChange() { emailForm.post('/profile/email', { preserveScroll: true }) }
function selectPhoto(event: Event) { profileForm.profile_photo = (event.target as HTMLInputElement).files?.[0] || null }
function deleteAccount() {
  if (!deleteForm.processing) deleteConfirmationOpen.value = true
}
function confirmDeleteAccount() {
  deleteConfirmationOpen.value = false
  deleteForm.delete('/profile', { preserveScroll: true })
}
</script>
