le:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" type="password" autocomplete="new-password" placeholder="Repita a nova senha" /></div></div><SaveActionButton label="Salvar alterações" :required-incomplete="profileRequiredIncomplete" :processing="profileForm.processing" /></form>
      <form class="panel stack min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words grid grid-cols-12 gap-6 [&>*]:col-span-12" @submit.prevent="requestEmailChange"><div class="panel-heading mb-6 flex flex-wrap items-start justify-between gap-4 [&_p]:mt-2 [&_p]:text-sm [&_p]:leading-6 [&_p]:text-td-body"><div><h2>E-mail</h2><p>Alterações exigem confirmação no novo endereço.</p></div></div><p v-if="emailForm.errors.email" class="error-summary my-5 flex min-w-0 items-start gap-3 rounded-lg border border-td-red/25 bg-td-red/5 p-4 text-sm leading-6 text-td-red [&_svg]:size-5 [&_svg]:shrink-0" role="alert">{{ emailForm.errors.email }}</p><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="profile-email">Novo e-mail</label><input id="profile-email" v-model="emailForm.email" class="form-input w-full min-w-0 scroll-mt-28 rounded-lg border border-td-border bg-transparent px-4 py-2.5 text-sm leading-5 text-td-ink outline-none placeholder:text-td-body/70 focus:border-td-primary focus-visible:ring-2 focus-visible:ring-td-primary/15 disabled:cursor-not-allowed disabled:bg-td-soft disabled:text-td-body file:mr-3 file:rounded file:border-0 file:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" type="email" autocomplete="email" required placeholder="nome@empresa.com.br" /><button class="btn-secondary inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg border border-td-border bg-white px-4 py-2.5 text-sm leading-5 text-td-ink hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" type="submit" :disabled="emailForm.processing">{{ emailForm.processing ? 'Enviando…' : 'Solicitar troca de e-mail' }}</button></form></main>
      <aside class="stack grid min-w-0 gap-6"><section class="panel min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words"><h2>Segurança</h2><p class="form-help mt-2 text-sm leading-6 text-td-body">O segundo fator protege o acesso aos dados operacionais.</p><Link class="btn-text inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-lg px-3 py-2 text-td-primary hover:bg-td-soft focus-visible:outline-2 focus-visible:outline-td-primary disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-5 [&_svg]:shrink-0" href="/settings/security/two-factor">Abrir configurações de 2FA</Link></section><section class="panel min-w-0 rounded-lg border border-td-border bg-white p-6 shadow-td-card sm:p-8 [&_h2]:text-lg [&_h2]:font-medium [&_h2]:leading-7 [&_h2]:text-td-ink [&_h3]:font-medium [&_h3]:text-td-ink [&_dd]:break-words"><h2>Excluir conta</h2><p class="form-help mt-2 text-sm leading-6 text-td-body">A exclusão exige a senha atual e encerra o acesso à conta.</p><p v-if="deleteForm.errors.current_password" class="field-error text-sm leading-5 text-td-red" role="alert">{{ deleteForm.errors.current_password }}</p><label class="field-label block text-sm font-medium text-gray-700 dark:text-gray-400" for="delete-password">Senha atual</label><input id="delete-password" v-model="deleteForm.current_password" class="form-input w-full min-w-0 scroll-mt-28 rounded-lg border border-td-border bg-transparent px-4 py-2.5 text-sm leading-5 text-td-ink outline-none placeholder:text-td-body/70 focus:border-td-primary focus-visible:ring-2 focus-visible:ring-td-primary/15 disabled:cursor-not-allowed disabled:bg-td-soft disabled:text-td-body file:mr-3 file:rounded file:border-0 file:bg-td-soft file:px-3 file:py-1 file:text-sm file:text-td-primary" type="password" autocomplete="current-password" placeholder="Digite sua senha 